                                                            <Link
                                                                key={state.slug}
                                                                to={`/locais/criacao-de-sites-em-${state.slug}`}
                                                                className="header__dropdown-item"
                                                            >
                                                                {state.abbr} - {state.name}
                                                            </Link>
                                                        ))}
                                                    </div>
                                                </motion.div>
                                            )}
                                        </AnimatePresence>
                                    </div>
                                ) : (
                                    <Link
                                        to={link.path}
                                        className={`header__nav-link ${location.pathname === link.path ? 'header__nav-link--active' : ''}`}
                                    >
                                        {link.name}
                                    </Link>
                                )}
                            </li>
                        ))}
                    </ul>
                </nav>

                <div className="header__actions">
                    <ThemeToggle />
                    <a
                        href={getWhatsAppLink()}
                        target="_blank"
                        rel="noopener noreferrer"
                        className="btn btn-primary header__cta"
                    >
                        <FaWhatsapp size={18} />
                        <span>Fale no WhatsApp</span>
                    </a>
                </div>

                <button
                    className="header__menu-toggle"
                    onClick={() => setIsMenuOpen(!isMenuOpen)}
                    aria-label="Toggle menu"
                >
                    {isMenuOpen ? <X size={24} /> : <Menu size={24} />}
                </button>
            </div>

            {/* Mobile Menu */}
            <AnimatePresence>
                {isMenuOpen && (
                    <motion.div
                        className="header__mobile-menu"
                        initial={{ opacity: 0, height: 0 }}
                        animate={{ opacity: 1, height: 'auto' }}
                        exit={{ opacity: 0, height: 0 }}
                        transition={{ duration: 0.3 }}
                    >
                        <ul className="header__mobile-nav">
                            {navLinks.map((link) => (
                                <li key={link.name}>
                                    {link.hasDropdown ? (
                                        <>
                                            <button
                                                className="header__mobile-link"
                                                onClick={() => setIsLocaisOpen(!isLocaisOpen)}
                                            >
                                                {link.name}
                                                <ChevronDown
                                                    size={16}
                                                    className={`header__dropdown-icon ${isLocaisOpen ? 'header__dropdown-icon--open' : ''}`}
                                                />
                                            </button>
                                            <AnimatePresence>
                                                {isLocaisOpen && (
                                                    <motion.div
                                                        className="header__mobile-dropdown"
                                                        initial={{ opacity: 0, height: 0 }}
