                                                )}
                                            </AnimatePresence>
                                        </>
                                    ) : (
                                        <Link to={link.path} className="header__mobile-link">
                                            {link.name}
                                        </Link>
                                    )}
                                </li>
                            ))}
                            <li>
                                <a
                                    href={getWhatsAppLink()}
                                    target="_blank"
                                    rel="noopener noreferrer"
                                    className="btn btn-primary header__mobile-cta"
                                >
                                    <FaWhatsapp size={18} />
                                    Fale no WhatsApp
                                </a>
                            </li>
                        </ul>
                    </motion.div>
                )}
            </AnimatePresence>
        </header>
    );
};

