                                    <motion.div
                                        key={service.id}
                                        className="state-service-card"
                                        initial={{ opacity: 0, y: 30 }}
                                        whileInView={{ opacity: 1, y: 0 }}
                                        viewport={{ once: true }}
                                        transition={{ duration: 0.5, delay: index * 0.1 }}
                                    >
                                        <div className="state-service-card__icon">
                                            <Icon size={24} />
                                        </div>
                                        <h3>{service.title}</h3>
                                        <p>{service.shortDescription}</p>
